	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+jane.ID, e.Acme.Key, map[string]any{"name": "Jane Q. Doe", "metadata": map[string]string{"crm": "7"}}, &got)
	if got.Name != "Jane Q. Doe" || got.Metadata["crm"] != "7" || got.Email != "jane@example.com" {
