// CustomerRecord is one customer of an import, and the line of the file where its record starts.
type CustomerRecord struct {
	Line                 int
	Name, Email          string
	DefaultPaymentMethod string
	Metadata             map[string]string
}

// RecordProblem is why one record of an import cannot be created: its line and a code ("missing_name", "invalid_email",
// "invalid_payment_method", "email_taken" or "duplicate_email").
type RecordProblem struct {
	Line int
	Code string
}

// ImportCustomers creates customers from records, all or none. Every record is checked as CreateCustomer checks a customer,
// and also against the organization's existing customers and the earlier records. When any record has a problem, nothing is
// created and the problems are returned in file order. The checks and the creation happen under one lock. A dry run checks
// only.
func (s *Store) ImportCustomers(orgID string, recs []CustomerRecord, now time.Time, dryRun bool) ([]Customer, []RecordProblem, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return nil, nil, ErrNotFound
	}
	if probs := s.checkImport(orgID, recs); len(probs) > 0 {
		return nil, probs, nil
	}
	if dryRun {
		return nil, nil, nil
	}
	out := make([]Customer, 0, len(recs))
	for _, r := range recs {
		c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: strings.TrimSpace(r.Name), Email: strings.TrimSpace(r.Email),
			DefaultPaymentMethod: r.DefaultPaymentMethod, Metadata: r.Metadata, CreatedAt: now.UTC()}
		s.customers[c.ID] = c
		s.customersByEmail[normEmail(c.Email)] = c.ID
		out = append(out, copyCustomer(c))
	}
	return out, nil, nil
}

// checkImport returns the problems of the records, in order, with the first that applies to each. The caller holds the lock.
func (s *Store) checkImport(orgID string, recs []CustomerRecord) []RecordProblem {
	var probs []RecordProblem
	seen := map[string]bool{} // normalized emails of the earlier records
	for _, r := range recs {
		name, email := strings.TrimSpace(r.Name), strings.TrimSpace(r.Email)
		key := normEmail(email)
		code := ""
		switch {
		case name == "":
			code = "missing_name"
		case !validEmail(email):
			code = "invalid_email"
		case r.DefaultPaymentMethod != "" && !strings.HasPrefix(r.DefaultPaymentMethod, "pm_"):
			code = "invalid_payment_method"
		case s.emailTaken(orgID, key):
			code = "email_taken"
		case seen[key]:
			code = "duplicate_email"
		}
		if code != "" {
			probs = append(probs, RecordProblem{Line: r.Line, Code: code})
		}
		if validEmail(email) {
			seen[key] = true
		}
	}
	return probs
}

// emailTaken reports whether one of the organization's customers has this normalized email address. The caller holds the lock.
func (s *Store) emailTaken(orgID, key string) bool {
	id, ok := s.customersByEmail[key]
	return ok && s.customers[id].OrgID == orgID
}

