		c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: strings.TrimSpace(r.Name), Email: strings.TrimSpace(r.Email),
			DefaultPaymentMethod: r.DefaultPaymentMethod, Metadata: r.Metadata, CreatedAt: now.UTC()}
		s.customers[c.ID] = c
		s.customersByEmail[normEmail(c.Email)] = c.ID
		out = append(out, copyCustomer(c))
	}
	return out, nil, nil
}

// checkImport returns the problems of the records, in order, with the first that applies to each. The caller holds the lock.
func (s *Store) checkImport(orgID string, recs []CustomerRecord) []RecordProblem {
	var probs []RecordProblem
	seen := map[string]bool{} // normalized emails of the earlier records
	for _, r := range recs {
		name, email := strings.TrimSpace(r.Name), strings.TrimSpace(r.Email)
		key := normEmail(email)
		code := ""
		switch {
		case name == "":
			code = "missing_name"
		case !validEmail(email):
			code = "invalid_email"
		case r.DefaultPaymentMethod != "" && !strings.HasPrefix(r.DefaultPaymentMethod, "pm_"):
			code = "invalid_payment_method"
		case s.emailTaken(orgID, key):
			code = "email_taken"
		case seen[key]:
			code = "duplicate_email"
		}
		if code != "" {
			probs = append(probs, RecordProblem{Line: r.Line, Code: code})
		}
		if validEmail(email) {
			seen[key] = true
		}
	}
	return probs
}

// emailTaken reports whether one of the organization's customers has this normalized email address. The caller holds the lock.
func (s *Store) emailTaken(orgID, key string) bool {
	id, ok := s.customersByEmail[key]
	return ok && s.customers[id].OrgID == orgID
}

