	wantBody(t, e.Do("POST", path, e.Acme.Key, rows(10001)), http.StatusRequestEntityTooLarge, `{"error":"too_many_rows"}`)
	wantBody(t, e.Do("POST", path+"?dry_run=true", e.Acme.Key, rows(10001)), http.StatusRequestEntityTooLarge, `{"error":"too_many_rows"}`)
	if n := count(); n != 3 {
		t.Fatalf("customers = %d after refused imports, want 3", n)
	}
}

