const maxImportRows = 10000

// importCodes are the status for each code that refuses a whole import.
var importCodes = map[string]int{
	"invalid_header": http.StatusUnprocessableEntity,
	"invalid_csv":    http.StatusBadRequest,
	"too_many_rows":  http.StatusRequestEntityTooLarge,
}

// rowError is one refused record of an import.
type rowError struct {
	Row   int    `json:"row"`
	Error string `json:"error"`
}

// importCustomers creates the customers in a CSV body (see parseCustomerCSV), all or none. ?dry_run=true only checks.
func (s *Server) importCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	body, err := io.ReadAll(r.Body)
	if err != nil {
		writeJSON(w, importCodes["invalid_csv"], map[string]string{"error": "invalid_csv"})
		return
	}
	recs, code := parseCustomerCSV(body)
	if code != "" {
		writeJSON(w, importCodes[code], map[string]string{"error": code})
		return
	}
	dry, _ := strconv.ParseBool(r.URL.Query().Get("dry_run"))
	cs, probs, err := s.store.ImportCustomers(p.OrgID, recs, s.clock.Now(), dry)
	if err != nil {
		s.storeError(w, err)
		return
	}
	if len(probs) > 0 {
		rows := make([]rowError, len(probs))
		for i, pr := range probs {
			rows[i] = rowError{Row: pr.Line, Error: pr.Code}
		}
		writeJSON(w, http.StatusUnprocessableEntity, map[string]any{"error": "invalid_rows", "rows": rows})
		return
	}
	if dry {
		writeJSON(w, http.StatusOK, map[string]int{"created": 0, "would_create": len(recs)})
		return
	}
	for _, c := range cs {
		s.publish(r.Context(), p.OrgID, "customer.created", c)
	}
	writeJSON(w, http.StatusCreated, map[string]any{"created": len(cs), "items": cs})
}

// parseCustomerCSV reads an import body: a header row, then one record per customer. The header names "name" and "email"
// (required), "default_payment_method" and "metadata.<key>" columns; names match ignoring case and surrounding spaces, and
// other columns are ignored. A byte order mark is skipped and blank lines are skipped. It returns the code for a body that
// cannot be imported, or "" with the records.
func parseCustomerCSV(body []byte) ([]store.CustomerRecord, string) {
	if !utf8.Valid(body) {
		return nil, "invalid_csv"
	}
	body = bytes.TrimPrefix(body, []byte("\xef\xbb\xbf"))
	cr := csv.NewReader(bytes.NewReader(body))
	cr.FieldsPerRecord = -1 // checked below, so that a line of spaces counts as blank
	header, err := readRecord(cr)
	if err == io.EOF {
		return nil, "invalid_header"
	}
	if err != nil {
		return nil, "invalid_csv"
	}

	const metaPrefix = "metadata."
	type metaColumn struct {
		col int
		key string
	}
	cols := map[string]int{} // "name", "email", "default_payment_method" -> column
	var metas []metaColumn
	seenKey := map[string]bool{}
	for i, h := range header {
		orig := strings.TrimSpace(h)
		name := strings.ToLower(orig)
		switch {
		case name == "name" || name == "email" || name == "default_payment_method":
			if _, dup := cols[name]; !dup {
				cols[name] = i
			}
		case len(orig) > len(metaPrefix) && strings.EqualFold(orig[:len(metaPrefix)], metaPrefix):
			key := strings.TrimSpace(orig[len(metaPrefix):])
			if key != "" && !seenKey[key] {
				seenKey[key] = true
				metas = append(metas, metaColumn{col: i, key: key})
			}
		}
	}
	_, hasName := cols["name"]
	_, hasEmail := cols["email"]
	if !hasName || !hasEmail {
		return nil, "invalid_header"
	}

	var recs []store.CustomerRecord
	for {
		fields, err := readRecord(cr)
		if err == io.EOF {
			break
		}
		if err != nil || len(fields) != len(header) {
			return nil, "invalid_csv"
		}
		if len(recs) == maxImportRows {
			return nil, "too_many_rows"
		}
		line, _ := cr.FieldPos(0)
		rec := store.CustomerRecord{Line: line, Name: fields[cols["name"]], Email: fields[cols["email"]]}
		if i, ok := cols["default_payment_method"]; ok {
			rec.DefaultPaymentMethod = fields[i]
		}
		for _, m := range metas {
			if v := fields[m.col]; v != "" {
				if rec.Metadata == nil {
					rec.Metadata = map[string]string{}
				}
				rec.Metadata[m.key] = v
			}
		}
		recs = append(recs, rec)
	}
	return recs, ""
}

// readRecord reads the next record that is not blank, or returns io.EOF.
func readRecord(cr *csv.Reader) ([]string, error) {
	for {
		fields, err := cr.Read()
		if err != nil || !blankRecord(fields) {
			return fields, err
		}
	}
}

func blankRecord(fields []string) bool {
	for _, f := range fields {
		if strings.TrimSpace(f) != "" {
			return false
		}
	}
	return true
}
