190	// parseCustomerCSV reads an import body: a header row, then one record per customer. The header names "name" and "email"
191	// (required), "default_payment_method" and "metadata.<key>" columns; names match ignoring case and surrounding spaces, and
192	// other columns are ignored. A byte order mark and blank lines are skipped. It returns the code for a body that cannot be
193	// imported, or "" with the records.
194	func parseCustomerCSV(body []byte) ([]store.CustomerRecord, string) {
195		if !utf8.Valid(body) {
196			return nil, "invalid_csv"
197		}
198		body = bytes.TrimPrefix(body, []byte("\xef\xbb\xbf"))
199		cr := csv.NewReader(bytes.NewReader(body))
200		cr.FieldsPerRecord = -1 // checked below, so that a line of spaces counts as blank
201		header, err := readRecord(cr)
202		if err == io.EOF {
203			return nil, "invalid_header"
204		}
205		if err != nil {
206			return nil, "invalid_csv"
207		}
208	
209		const metaPrefix = "metadata."
210		type metaColumn struct {
211			col int
212			key string
213		}
214		cols := map[string]int{} // "name", "email", "default_payment_method" -> column
215		var metas []metaColumn
216		seenKey := map[string]bool{}
217		for i, h := range header {
218			orig := strings.TrimSpace(h)
219			name := strings.ToLower(orig)
220			switch {
221			case name == "name" || name == "email" || name == "default_payment_method":
