154	// importCustomers creates the customers in a CSV body (see parseCustomerCSV), all or none. ?dry_run=true only checks.
155	func (s *Server) importCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
156		body, err := io.ReadAll(r.Body)
157		if err != nil {
158			writeJSON(w, importCodes["invalid_csv"], map[string]string{"error": "invalid_csv"})
159			return
160		}
161		recs, code := parseCustomerCSV(body)
162		if code != "" {
163			writeJSON(w, importCodes[code], map[string]string{"error": code})
164			return
165		}
166		dry, _ := strconv.ParseBool(r.URL.Query().Get("dry_run"))
167		cs, probs, err := s.store.ImportCustomers(p.OrgID, recs, s.clock.Now(), dry)
168		if err != nil {
169			s.storeError(w, err)
170			return
171		}
172		if len(probs) > 0 {
173			rows := make([]rowError, len(probs))
174			for i, pr := range probs {
175				rows[i] = rowError{Row: pr.Line, Error: pr.Code}
176			}
177			writeJSON(w, http.StatusUnprocessableEntity, map[string]any{"error": "invalid_rows", "rows": rows})
178			return
179		}
180		if dry {
181			writeJSON(w, http.StatusOK, map[string]int{"created": 0, "would_create": len(recs)})
182			return
183		}
184		for _, c := range cs {
185			s.publish(r.Context(), p.OrgID, "customer.created", c)
186		}
187		writeJSON(w, http.StatusCreated, map[string]any{"created": len(cs), "items": cs})
188	}
