39	// RecordProblem is why one record of an import cannot be created: its line and a code ("missing_name", "invalid_email",
40	// "invalid_payment_method", "email_taken" or "duplicate_email").
41	type RecordProblem struct {
42		Line int
43		Code string
44	}
