46	// ImportCustomers creates customers from records, all or none. Every record is checked as CreateCustomer checks a customer,
47	// and also against the organization's existing customers and the earlier records. When any record has a problem, nothing is
48	// created and the problems are returned in file order. The checks and the creation happen under one lock. A dry run checks
49	// only.
50	func (s *Store) ImportCustomers(orgID string, recs []CustomerRecord, now time.Time, dryRun bool) ([]Customer, []RecordProblem, error) {
51		s.mu.Lock()
52		defer s.mu.Unlock()
53		if _, ok := s.orgs[orgID]; !ok {
54			return nil, nil, ErrNotFound
55		}
56		if probs := s.checkImport(orgID, recs); len(probs) > 0 {
57			return nil, probs, nil
58		}
59		if dryRun {
60			return nil, nil, nil
61		}
62		out := make([]Customer, 0, len(recs))
63		for _, r := range recs {
64			c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: strings.TrimSpace(r.Name), Email: strings.TrimSpace(r.Email),
65				DefaultPaymentMethod: r.DefaultPaymentMethod, Metadata: r.Metadata, CreatedAt: now.UTC()}
66			s.customers[c.ID] = c
67			s.customersByEmail[normEmail(c.Email)] = c.ID
68			out = append(out, copyCustomer(c))
69		}
70		return out, nil, nil
71	}
