73	// checkImport returns the problems of the records, in order, with the first that applies to each. The caller holds the lock.
74	func (s *Store) checkImport(orgID string, recs []CustomerRecord) []RecordProblem {
75		var probs []RecordProblem
76		seen := map[string]bool{} // normalized emails of the earlier records
77		for _, r := range recs {
78			name, email := strings.TrimSpace(r.Name), strings.TrimSpace(r.Email)
79			key := normEmail(email)
80			code := ""
81			switch {
82			case name == "":
83				code = "missing_name"
84			case !validEmail(email):
85				code = "invalid_email"
86			case r.DefaultPaymentMethod != "" && !strings.HasPrefix(r.DefaultPaymentMethod, "pm_"):
87				code = "invalid_payment_method"
88			case s.emailTaken(orgID, key):
89				code = "email_taken"
90			case seen[key]:
91				code = "duplicate_email"
92			}
93			if code != "" {
94				probs = append(probs, RecordProblem{Line: r.Line, Code: code})
95			}
96			if validEmail(email) {
97				seen[key] = true
98			}
99		}
100		return probs
101	}
