165	// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change.
166	func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
167		s.mu.Lock()
168		defer s.mu.Unlock()
169		old, ok := s.customers[id]
170		if !ok || old.OrgID != orgID {
171			return Customer{}, ErrNotFound
172		}
173		c := copyCustomer(old)
174		if err := f(&c); err != nil {
175			return Customer{}, err
176		}
177		c.ID, c.OrgID, c.CreatedAt = old.ID, old.OrgID, old.CreatedAt
178		c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
179		if c.Name == "" || !validEmail(c.Email) {
180			return Customer{}, invalid("a customer needs a name and a valid email address")
181		}
182		if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
183			return Customer{}, invalid("a payment method looks like pm_...")
184		}
185		if newKey := normEmail(c.Email); newKey != normEmail(old.Email) {
186			if other, ok := s.customersByEmail[newKey]; ok && s.customers[other].OrgID == orgID {
187				return Customer{}, ErrEmailTaken
188			}
189			delete(s.customersByEmail, normEmail(old.Email))
190			s.customersByEmail[newKey] = c.ID
191		}
192		s.customers[id] = c
193		return copyCustomer(c), nil
194	}
