198		s.mu.Lock()
199		defer s.mu.Unlock()
200		c, ok := s.customers[id]
201		if !ok || c.OrgID != orgID {
202			return ErrNotFound
203		}
204		delete(s.customers, id)
205		if s.customersByEmail[normEmail(c.Email)] == id {
206			delete(s.customersByEmail, normEmail(c.Email))
207		}
208		return nil
209	}
