211	func copyCustomer(c Customer) Customer {
212		if c.Metadata != nil {
213			m := make(map[string]string, len(c.Metadata))
214			for k, v := range c.Metadata {
215				m[k] = v
216			}
217			c.Metadata = m
218		}
219		return c
220	}
