222	func sortCustomers(cs []Customer) {
223		sort.Slice(cs, func(i, j int) bool {
224			if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
225				return cs[i].CreatedAt.Before(cs[j].CreatedAt)
226			}
227			return cs[i].ID < cs[j].ID
228		})
229	}
