func TestImportEmailSharedAcrossOrgs(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	if _, err := s.CreateCustomer(a.ID, "Jane Doe", "jane@example.com", t0); err != nil {
		t.Fatal(err)
	}
	// Org B takes the same address later, which overwrites the global email index.
	if _, err := s.CreateCustomer(b.ID, "Jane Other", "jane@example.com", t0); err != nil {
		t.Fatal(err)
	}
	recs := []CustomerRecord{{Line: 2, Name: "Jane Again", Email: "JANE@example.com"}}
	out, probs, err := s.ImportCustomers(a.ID, recs, t0, false)
	if err != nil {
		t.Fatal(err)
	}
	if want := []RecordProblem{{Line: 2, Code: "email_taken"}}; !reflect.DeepEqual(probs, want) {
		t.Fatalf("problems = %+v, want %+v", probs, want)
	}
	if out != nil {
		t.Fatalf("created = %+v", out)
	}
	if got := s.Customers(a.ID); len(got) != 1 {
		t.Fatalf("org A has %d customers after a refused import", len(got))
	}
}

